import React, { useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { useHistory } from 'react-router-dom'
import { logout } from '../actions/userActions'
import './Navbar.css'

function NavBar() {

    const history = useHistory()
    const dispatch = useDispatch()

    const [search, setSearch] = useState('')


    // =========================================
    // USER
    // =========================================

    const userLoginReducer = useSelector(
        state => state.userLoginReducer
    )

    const { userInfo } = userLoginReducer


    // =========================================
    // SEARCH
    // =========================================

    const handleSearch = (event) => {

        event.preventDefault()

        const value = search.trim()

        if (value) {

            history.push(
                `/?searchTerm=${encodeURIComponent(value)}`
            )

        } else {

            history.push('/')
        }

    }


    // =========================================
    // LOGOUT
    // =========================================

    const logoutHandler = () => {

        dispatch(logout())

        history.push('/login')

    }


    // =========================================
    // CATEGORY NAVIGATION
    // =========================================

    const goToCategory = (category) => {

        if (category === 'Popular') {

            history.push('/')

        } else {

            history.push(
                `/?category=${encodeURIComponent(category)}`
            )

        }

    }


    // =========================================
    // SHOP EASE CATEGORIES
    // =========================================

    const categories = [

        {
            name: 'Popular',
            value: 'Popular'
        },

        {
            name: 'Women',
            value: 'Women'
        },

        {
            name: 'Men',
            value: 'Men'
        },

        {
            name: 'Home & Kitchen',
            value: 'Home & Kitchen'
        },

        {
            name: 'Beauty',
            value: 'Beauty'
        },

        {
            name: 'Jewellery',
            value: 'Jewellery'
        },

        {
            name: 'Bags',
            value: 'Bags'
        },

        {
            name: 'Footwear',
            value: 'Footwear'
        },

        {
            name: 'Electronics',
            value: 'Electronics'
        },

        {
            name: 'Watches',
            value: 'Watches'
        },

        {
            name: 'Sports',
            value: 'Sports'
        },

        {
            name: 'Groceries',
            value: 'Groceries'
        }

    ]


    // =========================================
    // RENDER
    // =========================================

    return (

        <header className="shopease-navbar">


            {/* =========================================
                TOP NAVBAR
            ========================================= */}

            <div className="navbar-container">


                {/* LOGO */}

                <div
                    className="shopease-logo"
                    onClick={() => history.push('/')}
                >

                    <div className="logo-icon">
                        🛍️
                    </div>


                    <div className="logo-text">

                        <h2>
                            Shop<span>Ease</span>
                        </h2>

                        <p>
                            Shop • Smile • Repeat
                        </p>

                    </div>

                </div>


                {/* SEARCH */}

                <form
                    className="navbar-search"
                    onSubmit={handleSearch}
                >

                    <span className="navbar-search-icon">
                        🔍
                    </span>


                    <input
                        type="text"
                        placeholder="Search for products, brands and more"
                        value={search}
                        onChange={(event) =>
                            setSearch(event.target.value)
                        }
                    />


                    <button type="submit">
                        Search
                    </button>

                </form>


                {/* RIGHT SIDE */}

                <div className="navbar-actions">


                    {/* PROFILE */}

                    {userInfo ? (

                        <div className="logged-user">

                            <div
                                className="profile-action"
                                onClick={() =>
                                    history.push('/account')
                                }
                            >

                                <span className="action-icon">
                                    👤
                                </span>


                                <div>

                                    <small>
                                        Hello,
                                    </small>

                                    <strong>
                                        {userInfo.username}
                                    </strong>

                                </div>

                            </div>


                            <button
                                className="logout-btn"
                                onClick={logoutHandler}
                            >
                                Logout
                            </button>

                        </div>

                    ) : (

                        <div
                            className="profile-action"
                            onClick={() =>
                                history.push('/login')
                            }
                        >

                            <span className="action-icon">
                                👤
                            </span>


                            <div>

                                <small>
                                    Hello,
                                </small>

                                <strong>
                                    Login
                                </strong>

                            </div>

                        </div>

                    )}


                    {/* CART */}

                    <div
                        className="cart-action"
                        onClick={() =>
                            alert("Cart feature coming next!")
                        }
                    >

                        <div className="cart-icon-wrapper">

                            🛒

                            <span className="cart-count">
                                0
                            </span>

                        </div>


                        <strong>
                            Cart
                        </strong>

                    </div>


                </div>

            </div>


            {/* =========================================
                CATEGORY NAVIGATION
            ========================================= */}

            <div className="category-navbar">

                {categories.map((category) => (

                    <button
                        key={category.name}
                        onClick={() =>
                            goToCategory(category.value)
                        }
                    >

                        {category.name}

                    </button>

                ))}

            </div>


        </header>

    )

}


export default NavBar
